const crypto = require('crypto');

const item = $input.first();
const headers = item.json.headers ?? {};

// The backend signed the exact bytes it sent, so sign-check those, not a re-serialised
// copy. "Raw Body" is on in the Webhook node; the JSON fallback only matters if someone
// turns it off, and it relies on JSON.parse preserving key order.
let raw;
if (item.binary && item.binary.data && item.binary.data.data) {
  raw = Buffer.from(item.binary.data.data, 'base64').toString('utf8');
} else {
  raw = JSON.stringify(item.json.body);
}

const inboundKey = $env.MP_INBOUND_KEY;
const requestSecret = $env.MP_REQUEST_SECRET;
if (!inboundKey || !requestSecret) {
  throw new Error('MP_INBOUND_KEY and MP_REQUEST_SECRET must be set on this n8n host.');
}

if (headers['x-mp-key'] !== inboundKey) {
  throw new Error('Rejected: wrong inbound key.');
}

const stamp = headers['x-mp-timestamp'];
const seconds = Number(stamp);
if (!Number.isFinite(seconds) || Math.abs(Date.now() / 1000 - seconds) > 300) {
  throw new Error('Rejected: timestamp outside the five minute window.');
}

const expected = 'sha256=' + crypto.createHmac('sha256', requestSecret).update(stamp + '.' + raw).digest('hex');
const given = String(headers['x-mp-signature'] ?? '');
const a = Buffer.from(given);
const b = Buffer.from(expected);
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
  throw new Error('Rejected: bad signature.');
}

const task = JSON.parse(raw);
if (task.schemaVersion !== '1') {
  throw new Error('Unsupported schemaVersion "' + task.schemaVersion + '".');
}

return [{ json: task }];

const task = $('Verify Signature').first().json;
const file = task.file;

const downloaded = $('Download File').first();
if (!downloaded.binary || !downloaded.binary.data) {
  throw new Error('The file could not be downloaded from the backend.');
}

const SCHEMAS = {
